<script setup lang="ts">
import { onMounted, ref } from 'vue'
import Button from 'primevue/button'; import InputText from 'primevue/inputtext'; import Textarea from 'primevue/textarea'; import ToggleSwitch from 'primevue/toggleswitch'
import { deleteAdminStaffMedia,deleteMedia,getAdminStaffForm,saveAdminStaffForm,uploadMedia,type AdminStaffForm,type MediaItem } from '@/api/admin'
const props=defineProps<{token:string;id:number|null}>();const emit=defineEmits<{saved:[];cancel:[]}>()
const form=ref<AdminStaffForm>({name:'',role:'',bio:'',initials:'',color:'#1a6757',photoMediaId:null,position:0,isPublished:false});const photo=ref<MediaItem|null>(null);const input=ref<HTMLInputElement|null>(null);const loading=ref(false);const error=ref('');const uploaded=new Set<number>();let original:number|null=null
onMounted(async()=>{if(!props.id)return;loading.value=true;try{form.value=await getAdminStaffForm(props.token,props.id);photo.value=form.value.photoMedia??null;original=photo.value?.id??null}catch(e){error.value=e instanceof Error?e.message:'Не удалось открыть форму'}finally{loading.value=false}})
async function upload(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;loading.value=true;try{const item=await uploadMedia(props.token,file,form.value.name);uploaded.add(item.id);photo.value=item;form.value.photoMediaId=item.id}catch(reason){error.value=reason instanceof Error?reason.message:'Не удалось загрузить фото'}finally{loading.value=false;if(input.value)input.value.value=''}}
async function remove(){if(!photo.value||!confirm('Удалить фотографию без возможности восстановления?'))return;loading.value=true;try{if(props.id&&photo.value.id===original){await deleteAdminStaffMedia(props.token,props.id,photo.value.id);original=null}else{await deleteMedia(props.token,photo.value.id);uploaded.delete(photo.value.id)};photo.value=null;form.value.photoMediaId=null}catch(e){error.value=e instanceof Error?e.message:'Не удалось удалить фото'}finally{loading.value=false}}
async function cancel(){await Promise.allSettled([...uploaded].map(id=>deleteMedia(props.token,id)));emit('cancel')}
async function save(){if(!form.value.name.trim()||!form.value.role.trim()){error.value='Заполните имя и должность';return};loading.value=true;try{await saveAdminStaffForm(props.token,form.value);if(original&&original!==form.value.photoMediaId)await deleteMedia(props.token,original);uploaded.clear();emit('saved')}catch(e){error.value=e instanceof Error?e.message:'Не удалось сохранить сотрудника'}finally{loading.value=false}}
</script>
<template><section class="form"><div class="heading"><div><p class="eyebrow">{{id?'Редактирование':'Новый сотрудник'}}</p><h2>{{id?(form.name||'Сотрудник'):'Добавить сотрудника'}}</h2></div><Button label="Закрыть" text @click="cancel"/></div><p v-if="error" class="form-error">{{error}}</p><div class="two"><label>Имя *<InputText v-model="form.name"/></label><label>Должность *<InputText v-model="form.role"/></label></div><label>Описание<Textarea v-model="form.bio" rows="5" auto-resize/></label><div class="two"><label>Инициалы<InputText v-model="form.initials" placeholder="АК"/></label><label>Цвет<div class="color"><input v-model="form.color" type="color"/><InputText v-model="form.color"/></div></label></div><div class="media"><div class="heading"><div><h3>Фотография</h3><p>Показывается в карточке сотрудника.</p></div><Button :label="photo?'Заменить':'Загрузить фото'" @click="input?.click()"/></div><input ref="input" hidden type="file" accept="image/*" @change="upload"/><article v-if="photo"><img :src="photo.url" :alt="photo.alt"/><Button label="Удалить фотографию" severity="danger" text @click="remove"/></article></div><div class="publish"><div><strong>Показывать на сайте</strong><small>{{form.isPublished?'Сотрудник опубликован':'Сохранится как черновик'}}</small></div><ToggleSwitch v-model="form.isPublished"/></div><div class="actions"><Button :label="id?'Сохранить изменения':'Добавить сотрудника'" :loading="loading" @click="save"/><Button label="Отмена" text @click="cancel"/></div></section></template>
<style scoped>.form{display:grid;gap:1.25rem}.heading,.publish{display:flex;justify-content:space-between;align-items:flex-start;gap:1rem}.heading h2,.heading h3{margin:0}.heading p:not(.eyebrow){margin:.3rem 0;color:#647067}.form label{display:grid;gap:.4rem;font-weight:700}.two{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.color{display:flex;gap:.5rem}.color input{width:3rem;border:1px solid #ddd;border-radius:7px}.media{border-top:1px solid #e6e2d9;padding-top:1.2rem}.media article{width:min(22rem,100%);display:grid;gap:.5rem;margin-top:1rem}.media img{width:100%;height:260px;object-fit:cover;border-radius:12px}.publish{align-items:center;padding:1rem;background:#e9f3ef;border-radius:12px}.publish div{display:grid}.actions{display:flex;gap:.5rem;border-top:1px solid #eee;padding-top:1rem}@media(max-width:650px){.two{grid-template-columns:1fr}}</style>
